// === Bootstrap 5 Theme Toggle with Cookie + System Preference ===

const THEME_COOKIE = 'theme';
const HTML_TAG = document.documentElement;
const THEME_BUTTONS = document.querySelectorAll('.btn-theme-options');

// --- Helpers ---
function getCookie(name) {
    const match = document.cookie.match(new RegExp('(^| )' + name + '=([^;]+)'));
    return match ? match[2] : null;
}

function setCookie(name, value, days = 365) {
    const expires = new Date(Date.now() + days * 864e5).toUTCString();
    document.cookie = `${name}=${value}; expires=${expires}; path=/; SameSite=Lax`;
}

function getSystemTheme() {
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}

// --- Apply theme and update button state ---
function applyTheme(theme) {
    let effectiveTheme = theme;

    // Handle "auto"
    if (theme === 'auto') {
        effectiveTheme = getSystemTheme();
    }

    // Apply theme to <html>
    HTML_TAG.setAttribute('data-bs-theme', effectiveTheme);

    // Update active state on buttons
    THEME_BUTTONS.forEach(btn => {
        const btnTheme = btn.getAttribute('data-theme');
        btn.classList.toggle('active', btnTheme === theme);
    });
}

// --- Initialize theme ---
function initTheme() {
    const savedTheme = getCookie(THEME_COOKIE);
    const theme = savedTheme || 'auto';
    applyTheme(theme);
}

// --- Handle click on any theme button ---
THEME_BUTTONS.forEach(btn => {
    btn.addEventListener('click', () => {
        const selectedTheme = btn.getAttribute('data-theme');
        setCookie(THEME_COOKIE, selectedTheme);
        applyTheme(selectedTheme);
    });
});

// --- Sync with system color changes only if in "auto" mode ---
window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', e => {
    const savedTheme = getCookie(THEME_COOKIE) || 'auto';
    if (savedTheme === 'auto') {
        applyTheme('auto');
    }
});

// --- Init on load ---
initTheme();
